# Test cases automatically generated by Pynguin (https://www.pynguin.eu).
# Please check them before you use them.
import ansible.plugins.inventory.yaml as module_0


def test_case_0():
    inventory_module_0 = module_0.InventoryModule()
    assert inventory_module_0.inventory is None
    assert (
        f"{type(inventory_module_0.display).__module__}.{type(inventory_module_0.display).__qualname__}"
        == "ansible.utils.display.Display"
    )
    assert (
        module_0.DOCUMENTATION
        == "\n    name: yaml\n    version_added: \"2.4\"\n    short_description: Uses a specific YAML file as an inventory source.\n    description:\n        - \"YAML-based inventory, should start with the C(all) group and contain hosts/vars/children entries.\"\n        - Host entries can have sub-entries defined, which will be treated as variables.\n        - Vars entries are normal group vars.\n        - \"Children are 'child groups', which can also have their own vars/hosts/children and so on.\"\n        - File MUST have a valid extension, defined in configuration.\n    notes:\n        - If you want to set vars for the C(all) group inside the inventory file, the C(all) group must be the first entry in the file.\n        - Whitelisted in configuration by default.\n    options:\n      yaml_extensions:\n        description: list of 'valid' extensions for files containing YAML\n        type: list\n        default: ['.yaml', '.yml', '.json']\n        env:\n          - name: ANSIBLE_YAML_FILENAME_EXT\n          - name: ANSIBLE_INVENTORY_PLUGIN_EXTS\n        ini:\n          - key: yaml_valid_extensions\n            section: defaults\n          - section: inventory_plugin_yaml\n            key: yaml_valid_extensions\n\n"
    )
    assert (
        module_0.EXAMPLES
        == "\nall: # keys must be unique, i.e. only one 'hosts' per group\n    hosts:\n        test1:\n        test2:\n            host_var: value\n    vars:\n        group_all_var: value\n    children:   # key order does not matter, indentation does\n        other_group:\n            children:\n                group_x:\n                    hosts:\n                        test5   # Note that one machine will work without a colon\n                #group_x:\n                #    hosts:\n                #        test5  # But this won't\n                #        test7  #\n                group_y:\n                    hosts:\n                        test6:  # So always use a colon\n            vars:\n                g2_var2: value3\n            hosts:\n                test4:\n                    ansible_host: 127.0.0.1\n        last_group:\n            hosts:\n                test1 # same host as above, additional group membership\n            vars:\n                group_last_var: value\n"
    )
    assert module_0.InventoryModule.NAME == "yaml"
    var_0 = inventory_module_0.verify_file(inventory_module_0)
    assert var_0 is False


